(()=>{'use strict';const dialog=document.createElement('dialog');dialog.className='mx-upgrade';dialog.setAttribute('aria-labelledby','upgrade-title');document.body.append(dialog);let trigger,previousOverflow;
function render(){const m=window.LINA_MARKET,p=m.state.prices,f=m.money;const keepFocus=dialog.open?document.activeElement?.className:null;dialog.innerHTML='<button type="button" class="upgrade-close" aria-label="Cerrar oferta">×</button><p class="upgrade-eyebrow">UNA CONDICIÓN ESPECIAL PARA TI</p><h2 id="upgrade-title">¿Solo la Mini Biblia?<br>Llévate la colección completa.</h2><p>En lugar de pagar <strong>'+f(p.basico)+'</strong> por los archivos de la Mini Biblia, agrega <strong>'+f(p.upgrade-p.basico)+'</strong> y llévate todas las piezas del Pack de Navidad.</p><div class="upgrade-price"><span>Colección completa <del>'+f(p.completo)+'</del></span><strong>'+f(p.upgrade)+'</strong><small>Total por la colección completa. No es un cargo adicional de '+f(p.upgrade)+'.</small></div><p>Mini Biblia, libreta, mini calendario, diseños para taza, canasta y empaques que combinan. Archivos digitales para imprimir y armar.</p><p class="local-price-note">'+(m.state.approximate?'Conversión aproximada. El total se confirma en Hotmart.':'Precio base en USD. El total se confirma en Hotmart.')+'</p><a class="btn-base btn-success upgrade-accept">SÍ, QUIERO EL COMPLETO POR '+f(p.upgrade)+'</a><a class="upgrade-decline">No, gracias. Solo la Mini Biblia por '+f(p.basico)+'</a><p class="upgrade-note">Pago único. Impresión, materiales y piezas físicas no incluidos.</p>';
for(const [css,plan] of [['.upgrade-accept','upgrade'],['.upgrade-decline','basico']]){const a=dialog.querySelector(css),value=window.OFERTA_CONFIG.checkouts[plan];a.href=window.hotmartDestination?window.hotmartDestination(value):value;}
dialog.querySelector('button').onclick=()=>dialog.close();if(keepFocus&&typeof keepFocus==='string'){const cls=keepFocus.split(' ').find(c=>c.startsWith('upgrade-'));if(cls)dialog.querySelector('.'+cls)?.focus();}}
render();document.addEventListener('lina:market-change',render);dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});dialog.addEventListener('close',()=>{document.body.style.overflow=previousOverflow||'';trigger?.focus({preventScroll:true});});
document.addEventListener('click',e=>{const anchor=e.target.closest('[data-checkout="basico"]');if(!anchor)return;e.preventDefault();e.stopImmediatePropagation();trigger=anchor;previousOverflow=document.body.style.overflow;render();dialog.showModal();document.body.style.overflow='hidden';},true);
})();